mapper.select:
select count(1)
from jiashu_xinxi js
join xitong_yonghu y on js.shouji = y.shouji
where y.id = #{yonghuId}
  and js.laoren_id = #{laorenId}

select l.id as laorenId, l.xingming as laorenXingming, f.loudong, f.louceng, f.fangjianhao, f.fangjian_leixing as fangjianLeixing, c.chuangweihao, c.zhuangtai as chuangweiZhuangtai, cs.kaishi_riqi as kaishiRiqi, hj.jibie_mingcheng as jibieMingcheng, hj.yue_feiyong as yueFeiyong, lh.shezhi_riqi as shezhiRiqi, lh.daoqi_riqi as daoqiRiqi from laoren_xinxi l
left join chuangwei_shiyong cs on l.id = cs.laoren_id and cs.shiyong_zhuangtai = '正在使用' left join fangjian_xinxi f on cs.fangjian_id = f.id left join chuangwei_xinxi c on cs.chuangwei_id = c.id left join laoren_huli lh on l.id = lh.laoren_id and lh.zhuangtai = '生效' left join huli_jibie hj on lh.jibie_id = hj.id where y.id = #{yonghuId}
and l.id = #{laorenId}
order by l.id desc

select jj.id, jj.laoren_id as laorenId, l.xingming as laorenXingming, hr.xingming as huliRenyuanXingming, jj.jiance_shijian as jianceShijian, jj.tiwen, jj.gaoya, jj.diya, jj.xinlv, jj.xueyang, jj.xuetang, jj.qingkuang from jiankang_jiance jj join laoren_xinxi l on jj.laoren_id = l.id
left join huli_renyuan hr on jj.huli_renyuan_id = hr.id where y.id = #{yonghuId}
and l.id = #{laorenId}
order by jj.jiance_shijian desc, jj.id desc

select yj.id, yj.laoren_id as laorenId, l.xingming as laorenXingming, yp.yaopin_mingcheng as yaopinMingcheng, yp.guige, yj.kaishi_riqi as kaishiRiqi, yj.jieshu_riqi as jieshuRiqi, yj.yongfa, yj.meiri_cishu as meiriCishu, yj.meici_yongliang as meiciYongliang, yj.yongyao_shijian as yongyaoShijian, yj.yizhu, yj.zhuangtai from yongyao_jihua yj join laoren_xinxi l on yj.laoren_id = l.id
join yaopin_xinxi yp on yj.yaopin_id = yp.id where y.id = #{yonghuId}
and l.id = #{laorenId}
order by yj.id desc

select fj.id, fj.laoren_id as laorenId, l.xingming as laorenXingming, hr.xingming as huliRenyuanXingming, yp.yaopin_mingcheng as yaopinMingcheng, yp.guige, fj.jihua_shijian as jihuaShijian, fj.shiji_shijian as shijiShijian, fj.zhixing_zhuangtai as zhixingZhuangtai, fj.beizhu from fuyao_jilu fj join laoren_xinxi l on fj.laoren_id = l.id
join yaopin_xinxi yp on fj.yaopin_id = yp.id left join huli_renyuan hr on fj.huli_renyuan_id = hr.id where y.id = #{yonghuId}
and l.id = #{laorenId}
order by fj.jihua_shijian desc, fj.id desc

mapper.update:
update laoren_xinxi
set touxiang = #{touxiang}
where id = #{laorenId}
